import { Component } from '@angular/core';
import { RecordFormComponent } from '../../../shared/record-form/record-form.component';
import { ProcesoJudicial } from '../../../models/proceso.judicial';
import { ProcesoJudicialService } from '../../../controllers/proceso.judicial.service';

import { FormsModule } from '@angular/forms';
import { BaseModel } from '../../../models/base.model';
import { EtapaJudicial } from '../../../models/etapa.judicial';
import { ActivatedRoute } from '@angular/router';
import { FormEtapaRowComponent } from "./form-etapa-row/form-etapa-row.component";
import { UtilsService } from '../../../services/utils.service';

@Component({
    selector: 'app-form-procesos-judiciales',
    imports: [
    FormsModule,
    FormEtapaRowComponent
],
    templateUrl: './form-procesos-judiciales.component.html',
    styleUrl: './form-procesos-judiciales.component.css'
})
export class FormProcesosJudicialesComponent extends RecordFormComponent<ProcesoJudicial> {
  override record: ProcesoJudicial ={
    nombre: '',
    id: 0,
    deleted_at: null,
    created_at: '',
    updated_at: null
  };

  etapas:EtapaJudicial[]=[]
  
  constructor(
    private procesoJudicialController:ProcesoJudicialService,
    public utils:UtilsService,
    private route:ActivatedRoute,
  ){
    super(procesoJudicialController)
  }

  override ngOnInit(){
    this.checkIfIsEditing()
    this.route.params.subscribe(async (params) =>{
      if(params['proceso_id']){
        const res= await this.procesoJudicialController.find(params['proceso_id'],['etapasJudiciales'])
        if(res){
          this.record= res
          this.etapas= res.etapas_judiciales??[]
          this.checkIfIsEditing()
        }
      }
    })
  }

  agregarEtapa(){
    this.etapas.push({
      nombre: '',
      proceso_judicial_id: this.record.id,
      id: 0,
      deleted_at: null,
      created_at: '',
      updated_at: null
    })
  }
}
